import { http, HttpResponse } from "msw";
import { FRONT_BASE } from "../api/config";

// in-memory DB (로컬 기반)
const KEY = "WOODEN_MSW_DB_v1";
const seed = {
  sellercustomer: [
    {
      cusNo: 1, 
      cusComp: "판매처 A", 
      cusName: "홍길동", 
      cusEmail: "a@test.com", 
      cusPhone: "010-1111-2222", 
      cusAddr: "서울 강남구"
    }
  ],

  itemlist: [],

  orderlist: [
    {
      orderNo: 1, 
      orderDate: "2025-10-02", 
      cusComp: "판매처 A", 
      itemName: "완제품 A", 
      orderQty: 19, 
      orderPrice: 300000,
      orderState: "승인대기", 
      orderDeliState: "납품대기", 
      deliveryDate: "2025-10-24", 
      cusAddr: "주소", 
      totalPrice: 5700000
    }
  ],

  completed: [],
  
  buyercustomer: [
    {
      buyerNo: 1,
      buyerComp: "구매처 A",
      buyerName: "강감찬",
      buyerEmail: "a@buyer.com",
      buyerPhone: "010-5555-1111",
      buyerAddr: "대전 유성구"
    }
  ],

  bom: [
    { bomId: 1, itemNo: 1, partNo: 1, qtyPerItem: 2 }
  ] ,

seq: { cusNo: 1, orderNo: 1, itemNo: 0, buyerNo: 1, bomId: 1, }


  
};

const load = () => {
  try {
    return JSON.parse(localStorage.getItem(KEY)) || seed;
  } catch {
    return seed;
  };
};

const save = (db) => {
  localStorage.setItem (KEY, JSON.stringify(db));
  return db;
};

const table = (name) => (load()[name] || []);

const setTable = (name, rows) => {
  const db = load(); db[name] = rows;
  save(db);
  return rows;
};

const nextId = (field) => {
  const db = load();
  db.seq[field] = (db.seq[field] || 0) + 1;
  save(db);
  return db.seq[field];
};

const upsert = (name, row, pk) => {
  const rows = table(name);
  if (!row[pk])
    row[pk] = nextId(pk);
  
  const i = rows.findIndex(r => r[pk] === row[pk]);
  if (i >= 0) 
    rows[i] = { ...rows[i], ...row };
  else rows.push(row);
  setTable(name, rows);
  return row;
};

const remove = (name, pk, id) => setTable(name, table(name).filter(r => r[pk] !== id));

const clone = (v) => JSON.parse(JSON.stringify(v));

// 엔드포인트 루트 와 FRONT_BASE 프리픽스 모두 등록
const PREFIXES = ["", FRONT_BASE.replace(/\/$/, "")];
const paths = (p) =>
  PREFIXES.map((pre) => `${pre}${p.startsWith("/") ? p : "/" + p}`);

export const handlers = [

  /* MAIN */

  // 예측 시계열
  ...paths("/forecast/series").map((p) =>
    http.get(p, ({ request }) => {
      const url = new URL(request.url);
      const h = Number(url.searchParams.get("h") || 12);
      const now = new Date();
      const series = Array.from({ length: h }, (_, k) => ({
        date: new Date(now.getFullYear(), now.getMonth() + k + 1, 1)
          .toISOString()
          .slice(0, 7),
        value: 100 + 5 * k + Math.random() * 8,
      }));
      return HttpResponse.json({
        itemNo: Number(url.searchParams.get("itemNo") || 1),
        series,
      });
    })
  ),

  /* ORDER */

  // 판매거래처
  ...paths("/order/sellercustomer").map((p) =>
    http.get(p, () => HttpResponse.json(clone(table("sellercustomer"))))
  ),
  ...paths("/order/sellercustomer").map((p) =>
    http.post(p, async ({ request }) => {
      const body = await request.json();
      const saved = upsert("sellercustomer", body, "cusNo");
      return HttpResponse.json(clone(saved));
    })
  ),
  ...paths("/order/sellercustomer/:cusNo").map((p) =>
    http.put(p, async ({ params, request }) => {
      const body = await request.json();
      const saved = upsert(
        "sellercustomer",
        { ...body, cusNo: Number(params.cusNo) },
        "cusNo"
      );
      return HttpResponse.json(clone(saved));
    })
  ),
  ...paths("/order/sellercustomer/:cusNo").map((p) =>
    http.delete(p, ({ params }) => {
      remove("sellercustomer", "cusNo", Number(params.cusNo));
      return HttpResponse.json({ success: true });
    })
  ),

  // 상품 주문서
  ...paths("/order/orderlist").map((p) =>
    http.get(p, () => HttpResponse.json(clone(table("orderlist"))))
  ),
  ...paths("/order/orderlist").map((p) =>
    http.post(p, async ({ request }) => {
      const body = await request.json();
      const row = upsert("orderlist", body, "orderNo");
      return HttpResponse.json(clone(row));
    })
  ),
  ...paths("/order/orderlist/:orderNo").map((p) =>
    http.put(p, async ({ params, request }) => {
      const body = await request.json();
      const id = Number(params.orderNo);
      const row = upsert("orderlist", { ...body, orderNo: id }, "orderNo");
      return HttpResponse.json(clone(row));
    })
  ),
  ...paths("/order/orderlist/:orderNo/status").map((p) =>
    http.patch(p, async ({ params, request }) => {
      const body = await request.json();
      const id = Number(params.orderNo);
      const rows = table("orderlist");
      const idx = rows.findIndex((r) => r.orderNo === id);
      if (idx >= 0) {
        rows[idx] = { ...rows[idx], ...body };
        setTable("orderlist", rows);
        return HttpResponse.json(clone(rows[idx]));
      }
      return HttpResponse.json(null, { status: 404 });
    })
  ),
  ...paths("/order/orderlist/:orderNo").map((p) =>
    http.delete(p, ({ params }) => {
      const id = Number(params.orderNo);
      remove("orderlist", "orderNo", id);
      return HttpResponse.json({ success: true });
    })
  ),

  // 주문 완료
  ...paths("/order/completed").map((p) =>
    http.get(p, () => HttpResponse.json(clone(table("completed"))))
  ),


  /* BUYER */

  // 구매 거래처
  ...paths("/buyer/buyercustomer").map((p) =>
    http.get(p, () => HttpResponse.json(clone(table("buyercustomer") || [])))
  ),
  ...paths("/buyer/buyercustomer").map((p) =>
    http.post(p, async ({ request }) => {
      const body = await request.json();
      const saved = upsert("buyercustomer", body, "buyerNo");
      return HttpResponse.json(clone(saved));
    })
  ),
  ...paths("/buyer/buyercustomer/:buyerNo").map((p) =>
    http.put(p, async ({ params, request }) => {
      const body = await request.json();
      const saved = upsert("buyercustomer", { ...body, buyerNo: Number(params.buyerNo) }, "buyerNo");
      return HttpResponse.json(clone(saved));
    })
  ),
  ...paths("/buyer/buyercustomer/:buyerNo").map((p) =>
    http.delete(p, ({ params }) => {
      remove("buyercustomer", "buyerNo", Number(params.buyerNo));
      return HttpResponse.json({ success: true });
    })
  ),

  
  /* PLAN */

  // 상품
  ...paths("/plan/itemlist").map((p) =>
    http.get(p, () => HttpResponse.json(clone(table("itemlist"))))
  ),
  ...paths("/plan/itemlist").map((p) =>
    http.post(p, async ({ request }) => {
      const body = await request.json();
      const saved = upsert("itemlist", body, "itemNo");
      return HttpResponse.json(clone(saved));
    })
  ),
  ...paths("/plan/itemlist/:itemNo").map((p) =>
    http.put(p, async ({ params, request }) => {
      const body = await request.json();
      const saved = upsert(
        "itemlist",
        { ...body, itemNo: Number(params.itemNo) },
        "itemNo"
      );
      return HttpResponse.json(clone(saved));
    })
  ),
  ...paths("/plan/itemlist/:itemNo").map((p) =>
    http.delete(p, ({ params }) => {
      remove("itemlist", "itemNo", Number(params.itemNo));
      return HttpResponse.json({ success: true });
    })
  ),

  // BOM 목록
  ...paths("/plan/bom").map((p) =>
    http.get(p, () => HttpResponse.json(clone(table("bom") || [])))
  ),
  // BOM 단건
  ...paths("/plan/bom/:bomId").map((p) =>
    http.get(p, ({ params }) => {
      const id = Number(params.bomId);
      const row = (table("bom") || []).find(r => r.bomId === id);
      return row ? HttpResponse.json(clone(row)) : HttpResponse.json(null, { status: 404 });
    })
  ),
  // BOM 등록
  ...paths("/plan/bom").map((p) =>
    http.post(p, async ({ request }) => {
      const body = await request.json();
      const saved = upsert("bom", body, "bomId");
      return HttpResponse.json(clone(saved));
    })
  ),
  // BOM 수정
  ...paths("/plan/bom/:bomId").map((p) =>
    http.put(p, async ({ params, request }) => {
      const body = await request.json();
      const saved = upsert("bom", { ...body, bomId: Number(params.bomId) }, "bomId");
      return HttpResponse.json(clone(saved));
    })
  ),
  // BOM 삭제
  ...paths("/plan/bom/:bomId").map((p) =>
    http.delete(p, ({ params }) => {
      remove("bom", "bomId", Number(params.bomId));
      return HttpResponse.json({ success: true });
    })
  ),

];
